+        nameField.addValueChangeListener(event -> sendButton.setEnabled(true));
+        emailField.addValueChangeListener(event -> sendButton.setEnabled(true));
+        phoneField.addValueChangeListener(event -> sendButton.setEnabled(true));
+        messageField.addValueChangeListener(event -> sendButton.setEnabled(true));
+
+        add(new VerticalLayout(nameField, emailField, phoneField, messageField, sendButton));
+
+        grid.addColumn(Message::name).setHeader("Name");
+        grid.addColumn(Message::email).setHeader("Email");
+        grid.addColumn(Message::phone).setHeader("Phone");
+        grid.addColumn(Message::message).setHeader("Message");
+        add(grid);
+
+        refreshGrid();
+    }
+
+    private void refreshGrid() {
+        grid.setItems(messageService.findAll());
+    }
+
+    private void send() {
+        if (!validate()) {
+            return;
+        }
+
+        messageService.add(new Message(nameField.getValue(), emailField.getValue(),
+                phoneField.getValue(), messageField.getValue()));
+        refreshGrid();
+
+        nameField.clear();
+        emailField.clear();
+        phoneField.clear();
+        messageField.clear();
+
+        sendButton.setEnabled(false);
+
+        Notification.show("Message sent");
+    }
+
+    private boolean validate() {
+        boolean valid = true;
+
+        if (nameField.getValue().isBlank()) {
+            nameField.setInvalid(true);
+            nameField.setErrorMessage("Name is required");
+            valid = false;
+        } else {
+            nameField.setInvalid(false);
+        }
+
+        String email = emailField.getValue();
+        String phone = phoneField.getValue();
+        if (!email.isBlank() && !EMAIL_PATTERN.matcher(email).matches()) {
+            emailField.setInvalid(true);
+            emailField.setErrorMessage("Enter a valid e-mail address");
+            valid = false;
+        } else if (email.isBlank() && phone.isBlank()) {
+            emailField.setInvalid(true);
+            emailField.setErrorMessage("Give an e-mail address or a phone number");
+            valid = false;
+        } else {
+            emailField.setInvalid(false);
+        }
+
+        String messageText = messageField.getValue();
+        if (messageText.isBlank()) {
+            messageField.setInvalid(true);
+            messageField.setErrorMessage("Message is required");
+            valid = false;
+        } else if (messageText.length() > MAX_MESSAGE_LENGTH) {
+            messageField.setInvalid(true);
+            messageField.setErrorMessage("Message must be at most 500 characters");
+            valid = false;
+        } else {
+            messageField.setInvalid(false);
+        }
+
+        return valid;
+    }
+
+    private boolean hasUnsavedInput() {
+        return !nameField.getValue().isBlank()
+                || !emailField.getValue().isBlank()
+                || !phoneField.getValue().isBlank()
+                || !messageField.getValue().isBlank();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+
+        BeforeLeaveEvent.ContinueNavigationAction action = event.postpone();
+
+        Dialog dialog = new Dialog();
+        dialog.add("You have unsaved changes. Leave anyway?");
+
+        Button keepEditing = new Button("Keep editing", click -> {
+            action.cancel();
+            dialog.close();
+        });
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            action.proceed();
+        });
+
+        dialog.getFooter().add(keepEditing, discard);
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+        dialog.open();
+    }
+}
