+package com.example.contact;
+
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.assertions.PlaywrightAssertions;
+import com.microsoft.playwright.options.AriaRole;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.springframework.test.annotation.DirtiesContext;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.ButtonElement;
+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.NotificationElement;
+import org.vaadin.addons.dramafinder.element.TextAreaElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+@DirtiesContext(classMode = DirtiesContext.ClassMode.AFTER_EACH_TEST_METHOD)
+class ContactViewBrowserIT extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Override
+    public String getView() {
+        return "/contact";
+    }
+
+    private void clickAboutLink() {
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+    }
+
+    @Test
+    void contactView_initialState_headingLinkAndEmptyEnabledForm() {
+        assertEquals("Contact", page.locator("h1").textContent());
+
+        assertEquals("", TextFieldElement.getByLabel(page, "Name").getValue());
+        assertEquals("", EmailFieldElement.getByLabel(page, "Email").getValue());
+        assertEquals("", TextFieldElement.getByLabel(page, "Phone").getValue());
+        assertEquals("", TextAreaElement.getByLabel(page, "Message").getValue());
+
+        ButtonElement.getByText(page, "Send").assertEnabled();
+    }
+
+    @Test
+    void send_emptyForm_marksFieldsInvalidWithoutSending() {
+        ButtonElement.getByText(page, "Send").click();
+
+        TextFieldElement.getByLabel(page, "Name").assertInvalid();
+        TextFieldElement.getByLabel(page, "Name").assertErrorMessage("Name is required");
+
+        EmailFieldElement.getByLabel(page, "Email").assertInvalid();
+        EmailFieldElement.getByLabel(page, "Email")
+                .assertErrorMessage("Give an e-mail address or a phone number");
+
+        TextAreaElement.getByLabel(page, "Message").assertInvalid();
+        TextAreaElement.getByLabel(page, "Message").assertErrorMessage("Message is required");
+
+        assertFalse(NotificationElement.getByText(page, "Message sent").isOpen());
+        GridElement.get(page).assertRowCount(0);
+    }
+
+    @Test
+    void send_validForm_sendsShowsNotificationAndUpdatesGrid() {
+        TextFieldElement.getByLabel(page, "Name").setValue("Jane Doe");
+        EmailFieldElement.getByLabel(page, "Email").setValue("jane@example.com");
+        TextAreaElement.getByLabel(page, "Message").setValue("Hello there");
+
+        ButtonElement.getByText(page, "Send").click();
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+
+        GridElement grid = GridElement.get(page);
+        grid.assertRowCount(1);
+        grid.assertCellContent(0, 0, "Jane Doe");
+
+        assertEquals("", TextFieldElement.getByLabel(page, "Name").getValue());
+        assertEquals("", EmailFieldElement.getByLabel(page, "Email").getValue());
+        assertEquals("", TextAreaElement.getByLabel(page, "Message").getValue());
+
+        ButtonElement.getByText(page, "Send").assertDisabled();
+
+        TextFieldElement.getByLabel(page, "Name").setValue("x");
+        ButtonElement.getByText(page, "Send").assertEnabled();
+    }
+
+    @Test
+    void leavingWithUnsavedInput_showsDialog_keepEditingStaysOnPage() {
+        TextFieldElement.getByLabel(page, "Name").setValue("Jane Doe");
+
+        clickAboutLink();
+
+        new DialogElement(page).assertOpen();
+
+        ButtonElement.getByText(page, "Keep editing").click();
+
+        new DialogElement(page).assertClosed();
+        assertEquals("Jane Doe", TextFieldElement.getByLabel(page, "Name").getValue());
+    }
+
+    @Test
+    void leavingWithUnsavedInput_discard_navigatesToAbout() {
+        TextFieldElement.getByLabel(page, "Name").setValue("Jane Doe");
+
+        clickAboutLink();
+        ButtonElement.getByText(page, "Discard").click();
+
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("About");
+    }
+}
