+package com.example.contact;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.test.annotation.DirtiesContext;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest
+@DirtiesContext(classMode = DirtiesContext.ClassMode.AFTER_EACH_TEST_METHOD)
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField name() {
+        return find(TextField.class).withLabel("Name").single();
+    }
+
+    private EmailField email() {
+        return find(EmailField.class).withLabel("Email").single();
+    }
+
+    private TextField phone() {
+        return find(TextField.class).withLabel("Phone").single();
+    }
+
+    private TextArea message() {
+        return find(TextArea.class).withLabel("Message").single();
+    }
+
+    private Button send() {
+        return find(Button.class).withText("Send").single();
+    }
+
+    private void fillValidForm() {
+        test(name()).setValue("Jane Doe");
+        test(email()).setValue("jane@example.com");
+        test(message()).setValue("Hello there");
+    }
+
+    @Test
+    void contactView_initialState_headingLinkAndEmptyEnabledForm() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", find(H1.class).single().getText());
+        assertTrue(find(RouterLink.class).withText("About").exists());
+
+        assertTrue(name().isEmpty());
+        assertTrue(email().isEmpty());
+        assertTrue(phone().isEmpty());
+        assertTrue(message().isEmpty());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void aboutLink_noUnsavedInput_navigatesWithoutDialog() {
+        navigate(ContactView.class);
+
+        test(find(RouterLink.class).withText("About").single()).click();
+
+        assertTrue(getCurrentView() instanceof AboutView);
+        assertFalse(find(Dialog.class).exists());
+    }
+
+    @Test
+    void aboutView_hasHeading() {
+        navigate(AboutView.class);
+
+        assertEquals("About", find(H1.class).single().getText());
+    }
+
+    @Test
+    void send_emptyForm_marksAllRequiredFieldsInvalidAndSendsNothing() {
+        navigate(ContactView.class);
+
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+
+        assertFalse(find(Notification.class).exists());
+        assertEquals(0, find(Grid.class).single().getListDataView().getItemCount());
+    }
+
+    @Test
+    void send_invalidEmailFormat_marksEmailInvalidWithFormatMessage() {
+        navigate(ContactView.class);
+
+        test(name()).setValue("Jane Doe");
+        test(email()).setValue("not-an-email");
+        test(message()).setValue("Hello there");
+
+        test(send()).click();
+
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertFalse(find(Notification.class).exists());
+    }
+
+    @Test
+    void send_phoneOnlyNoEmail_isValid() {
+        navigate(ContactView.class);
+
+        test(name()).setValue("Jane Doe");
+        test(phone()).setValue("555-1234");
+        test(message()).setValue("Hello there");
+
+        test(send()).click();
+
+        assertFalse(email().isInvalid());
+        assertTrue(find(Notification.class).exists());
+    }
+
+    @Test
+    void send_messageTooLong_marksMessageInvalid() {
+        navigate(ContactView.class);
+
+        test(name()).setValue("Jane Doe");
+        test(email()).setValue("jane@example.com");
+        test(message()).setValue("x".repeat(501));
+
+        test(send()).click();
+
+        assertTrue(message().isInvalid());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+        assertFalse(find(Notification.class).exists());
+    }
+
+    @Test
+    void send_validForm_sendsAndClearsAndDisablesSend() {
+        navigate(ContactView.class);
+
+        fillValidForm();
+        test(send()).click();
+
+        Notification notification = find(Notification.class).single();
+        assertTrue(test(notification).getText().contains("Message sent"));
+
+        Grid<Message> grid = find(Grid.class).single();
+        assertEquals(1, grid.getListDataView().getItemCount());
+        assertEquals("Jane Doe", grid.getListDataView().getItems().findFirst().get().name());
+
+        assertTrue(name().isEmpty());
+        assertTrue(email().isEmpty());
+        assertTrue(phone().isEmpty());
+        assertTrue(message().isEmpty());
+
+        assertFalse(send().isEnabled());
+    }
+
+    @Test
+    void send_afterSuccessfulSend_editingAFieldReEnablesSend() {
+        navigate(ContactView.class);
+
+        fillValidForm();
+        test(send()).click();
+        assertFalse(send().isEnabled());
+
+        test(name()).setValue("Someone else");
+
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void enterKey_validForm_sendsMessage() {
+        navigate(ContactView.class);
+
+        fillValidForm();
+        fireShortcut(Key.ENTER);
+
+        assertTrue(find(Notification.class).exists());
+    }
+
+    @Test
+    void messages_persistAcrossViewVisits() {
+        navigate(ContactView.class);
+        fillValidForm();
+        test(send()).click();
+
+        // Leave without a dialog (form is now empty) and come back.
+        test(find(RouterLink.class).withText("About").single()).click();
+        navigate(ContactView.class);
+
+        Grid<Message> grid = find(Grid.class).single();
+        assertEquals(1, grid.getListDataView().getItemCount());
+    }
+
+    @Test
+    void leavingWithUnsavedInput_showsConfirmationDialog() {
+        navigate(ContactView.class);
+        test(name()).setValue("Jane Doe");
+
+        test(find(RouterLink.class).withText("About").single()).click();
+
+        assertTrue(getCurrentView() instanceof ContactView);
+        assertTrue(find(Dialog.class).exists());
+    }
+
+    @Test
+    void leavingWithUnsavedInput_keepEditing_staysAndKeepsInput() {
+        navigate(ContactView.class);
+        test(name()).setValue("Jane Doe");
+
+        test(find(RouterLink.class).withText("About").single()).click();
+        test(find(Button.class).withText("Keep editing").single()).click();
+
+        assertTrue(getCurrentView() instanceof ContactView);
+        assertFalse(find(Dialog.class).exists());
+        assertEquals("Jane Doe", name().getValue());
+    }
+
+    @Test
+    void leavingWithUnsavedInput_discard_navigatesAway() {
+        navigate(ContactView.class);
+        test(name()).setValue("Jane Doe");
+
+        test(find(RouterLink.class).withText("About").single()).click();
+        test(find(Button.class).withText("Discard").single()).click();
+
+        assertTrue(getCurrentView() instanceof AboutView);
+    }
+}
